import fs from "node:fs";
import path from "node:path";

const rows = JSON.parse(Buffer.from("", "base64").toString("utf8"));
if (rows.length !== 10) throw new Error("Unexpected record count");
const root = path.resolve(".cache/getlink-history-2026-10-07");
fs.mkdirSync(root, { recursive: true });
const format = new Intl.DateTimeFormat("vi-VN", { timeZone: "Asia/Saigon", dateStyle: "short", timeStyle: "medium" });
const display = rows.map(row => ({ ...row, localTime: format.format(new Date(row.createdAt)) }));
const total = rows.reduce((sum, row) => sum + Number(row.creditUsed || 0), 0);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const csvCell = value => {
  let s = String(value ?? "");
  if (/^[=+@\-\t\r]/.test(s)) s = "'" + s;
  return '"' + s.replaceAll('"', '""') + '"';
};
const csv = [["Thoi gian Viet Nam", "Ma model", "Ten model", "Credit", "Link user gui", "Link da lam sach"],
  ...display.map(row => [row.localTime, row.productId, row.title, row.creditUsed, "Khong con trong database hien tai", "Can kiem tra backup"])].map(row => row.map(csvCell).join(",")).join("\r\n");
fs.writeFileSync(path.join(root, "getlink-2026-10-07.csv"), "\uFEFF" + csv, "utf8");
fs.writeFileSync(path.join(root, "getlink-2026-10-07.json"), JSON.stringify({ day: "2026-10-07", timezone: "Asia/Saigon", source: "production-core-read-only", totalCredit: total, linkStatus: "Not present in current database; encrypted backup not yet read.", rows: display }, null, 2), "utf8");
const html = `<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Lịch sử Getlink 07/10/2026</title><style>
body{font:15px/1.6 system-ui,sans-serif;color:#17221e;background:#f5f7f6;margin:0;padding:32px}main{max-width:1300px;margin:auto}h1{font-size:26px;margin:0 0 8px}p{margin:8px 0}.summary{margin:22px 0;padding:14px 0;border-block:1px solid #cbd5d0}.notice{color:#715114}nav{margin:18px 0;display:flex;gap:24px}a{color:#006f4b}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;border-bottom:1px solid #d6dfda;padding:12px;vertical-align:top}th{background:#e7eee9;font-size:13px}td:nth-child(2){font:13px/1.7 ui-monospace,monospace}td:first-child{white-space:nowrap}td:last-child{text-align:right}.note{color:#56665d;font-size:13px;margin-top:18px}@media(max-width:650px){body{padding:16px}h1{font-size:22px}}
</style><main><h1>Lịch sử Getlink ngày 07/10/2026</h1><p>Múi giờ Việt Nam (UTC+7). Bản xuất chỉ đọc; không khôi phục hoặc sửa dữ liệu trên web.</p><div class="summary"><strong>${rows.length} lượt Getlink</strong> · Tổng <strong>${total} Credit</strong></div><p class="notice">Link user gửi và link đã làm sạch không còn trong database hiện tại. Cả 10 lượt được đánh dấu dọn chi tiết lúc 02:31:53 ngày 16/10/2026 (giờ Việt Nam). Bản backup trước thời điểm này vẫn cần được giải mã để kiểm tra; chưa xác nhận có đủ link.</p><nav><a href="getlink-2026-10-07.csv">CSV</a><a href="getlink-2026-10-07.json">JSON</a></nav><div class="table-wrap"><table><thead><tr><th>Thời gian Việt Nam</th><th>Mã model</th><th>Tên model gốc</th><th>Credit</th></tr></thead><tbody>${display.map(row=>`<tr><td>${esc(row.localTime)}</td><td>${esc(row.productId)}</td><td>${esc(row.title)}</td><td>${esc(row.creditUsed)}</td></tr>`).join("")}</tbody></table></div><p class="note">Bản này không chứa email, cookie, token đăng nhập hoặc link tải file. Nguồn: collection Getlink trên Core, lọc từ 00:00 đến trước 00:00 ngày kế tiếp theo giờ Việt Nam.</p></main></html>`;
fs.writeFileSync(path.join(root, "index.html"), html, "utf8");
console.log(JSON.stringify({ root, records: rows.length, totalCredit: total }));

